class SecurityConfig {
    public static final int MAX_LOGIN_ATTEMPTS = 5;
    public static final int PASSWORD_EXPIRY_DAYS = 90;
}

public class User {
    private String name;
    private String email;
    private String password;
    private boolean isActive;
    private String role;
    private java.util.Date lastLogin;
    private int loginAttempts;
    private String phoneNumber;
    private java.util.Date registrationDate;
    private java.util.List<String> loginHistory;
    private java.util.Map<String, String> preferences;
    private String profilePictureUrl;
    private boolean emailVerified;
    private java.util.List<String> notifications;

    private DatabaseService dbService;
    private EmailService emailService;
    private SMSService smsService;
    private FileService fileService;

    public User(String name, String email) {
        this.name = name;
        this.email = email;
        this.isActive = true;
        this.role = "USER";
        this.loginAttempts = 0;
        this.registrationDate = new java.util.Date();
        this.loginHistory = new java.util.ArrayList<>();
        this.preferences = new java.util.HashMap<>();
        this.notifications = new java.util.ArrayList<>();
        this.emailVerified = false;

        this.dbService = new DatabaseService("jdbc:mysql://localhost:3306/userdb");
        this.emailService = new EmailService("smtp.company.com", 587);
        this.smsService = new SMSService("api_key_12345");
        this.fileService = new FileService("/uploads");

        initializeDefaultPreferences();
    }

    public void saveToDatabase() {
        dbService.saveUser(this);
    }

    public void sendWelcomeEmail() {
        String subject = "Welcome to our platform!";
        String body = createWelcomeEmailBody();
        emailService.sendEmail(email, subject, body);
    }

    public void sendPasswordResetEmail() {
        String resetToken = generatePasswordResetToken();
        String subject = "Password Reset Request";
        String body = createPasswordResetEmailBody(resetToken);
        emailService.sendEmail(email, subject, body);
    }

    public void sendSMSVerification() {
        if (phoneNumber != null) {
            String smsCode = generateSMSVerificationCode();
            String message = "Your verification code: " + smsCode;
            smsService.sendSMS(phoneNumber, message);
        }
    }

    public String createWelcomeEmailBody() {
        return "Dear " + name + ",\n\nWelcome to our platform! Complete your profile and explore our features.\n\nBest regards,\nThe Team";
    }

    public String createPasswordResetEmailBody(String token) {
        return "Hello " + name + ",\n\nReset your password: https://oursite.com/reset?token=" + token + "\n\nLink expires in 24 hours.";
    }

    public String generatePasswordResetToken() {
        long timestamp = System.currentTimeMillis();
        double random = Math.random();
        return "RESET_" + timestamp + "_" + String.valueOf(random).substring(2, 8);
    }

    public String generateSMSVerificationCode() {
        return String.valueOf((int)(Math.random() * 900000) + 100000);
    }

    public boolean validateEmailFormat(String email) {
        if (email == null || email.trim().isEmpty()) {
            return false;
        }
        return email.contains("@") && email.contains(".") && email.split("@").length == 2;
    }

    public boolean validatePasswordStrength(String password) {
        if (password == null || password.length() < 8) {
            return false;
        }

        boolean hasUpper = false, hasLower = false, hasDigit = false, hasSpecial = false;

        for (char c : password.toCharArray()) {
            if (Character.isUpperCase(c)) hasUpper = true;
            else if (Character.isLowerCase(c)) hasLower = true;
            else if (Character.isDigit(c)) hasDigit = true;
            else if ("!@#$%^&*()_+-=[]{}|;:,.<>?".indexOf(c) != -1) hasSpecial = true;
        }

        return hasUpper && hasLower && hasDigit && hasSpecial;
    }

    public String hashPassword(String password) {
        int hash = 7;
        for (int i = 0; i < password.length(); i++) {
            hash = hash * 31 + password.charAt(i);
        }
        return "HASH:" + Integer.toHexString(Math.abs(hash)).toUpperCase();
    }

    public boolean verifyPassword(String plainPassword, String hashedPassword) {
        String computedHash = hashPassword(plainPassword);
        return computedHash.equals(hashedPassword);
    }

    public boolean authenticate(String password) {
        if (loginAttempts >= SecurityConfig.MAX_LOGIN_ATTEMPTS) {
            System.out.println("Account locked due to too many failed attempts");
            return false;
        }

        if (this.password != null && verifyPassword(password, this.password)) {
            loginAttempts = 0;
            lastLogin = new java.util.Date();
            addToLoginHistory("Successful login from IP: 192.168.1.100");
            return true;
        }

        loginAttempts++;
        addToLoginHistory("Failed login attempt from IP: 192.168.1.100");
        return false;
    }

    public void lockAccount() {
        this.isActive = false;
        logSecurityEvent("ACCOUNT_LOCKED", "Account locked for user: " + name);
        sendAccountNotification("Your account has been locked due to security reasons.");
    }

    public void unlockAccount() {
        this.isActive = true;
        this.loginAttempts = 0;
        logSecurityEvent("ACCOUNT_UNLOCKED", "Account unlocked for user: " + name);
        sendAccountNotification("Your account has been successfully unlocked.");
    }

    public void logSecurityEvent(String eventType, String description) {
        java.util.Date timestamp = new java.util.Date();
        String logEntry = "[" + timestamp + "] " + eventType + ": " + description;
        System.out.println("SECURITY LOG: " + logEntry);
    }

    public void sendAccountNotification(String message) {
        addNotification(message);
        if (emailVerified) {
            emailService.sendEmail(email, "Account Security Alert", message);
        }
        if (phoneNumber != null) {
            smsService.sendSMS(phoneNumber, "Security Alert: " + message);
        }
    }

    public void addToLoginHistory(String entry) {
        String timestampedEntry = new java.util.Date() + ": " + entry;
        loginHistory.add(timestampedEntry);
        if (loginHistory.size() > 100) {
            loginHistory.remove(0);
        }
    }

    public void initializeDefaultPreferences() {
        preferences.put("theme", "light");
        preferences.put("language", "en");
        preferences.put("notifications", "enabled");
    }

    public void updatePreference(String key, String value) {
        String oldValue = preferences.get(key);
        preferences.put(key, value);
        logPreferenceChange(key, oldValue, value);
    }

    public void logPreferenceChange(String key, String oldValue, String newValue) {
        String logEntry = "Preference '" + key + "' changed from '" + oldValue + "' to '" + newValue + "'";
        System.out.println("PREFERENCE LOG: " + logEntry);
    }

    public String getPreference(String key) {
        return preferences.get(key);
    }

    public void uploadProfilePicture(byte[] imageData, String fileName) {
        if (validateImageFile(imageData, fileName)) {
            this.profilePictureUrl = fileService.uploadFile(imageData, "profile_" + name + "_" + fileName);
            logActivityEvent("PROFILE_PICTURE_UPLOADED", "User uploaded new profile picture");
        } else {
            throw new IllegalArgumentException("Invalid image file");
        }
    }

    public boolean validateImageFile(byte[] imageData, String fileName) {
        if (imageData == null || imageData.length == 0 || imageData.length > 5 * 1024 * 1024) {
            return false;
        }
        String lower = fileName.toLowerCase();
        return lower.endsWith(".jpg") || lower.endsWith(".jpeg") || lower.endsWith(".png") || lower.endsWith(".gif");
    }

    public void logActivityEvent(String eventType, String description) {
        java.util.Date timestamp = new java.util.Date();
        String logEntry = "[" + timestamp + "] " + eventType + ": " + description + " (User: " + name + ")";
        System.out.println("ACTIVITY LOG: " + logEntry);
    }

    public void addNotification(String message) {
        String timestampedNotification = new java.util.Date() + ": " + message;
        notifications.add(timestampedNotification);
        if (notifications.size() > 50) {
            notifications.remove(0);
        }
    }

    public void changePassword(String oldPassword, String newPassword) {
        if (!authenticate(oldPassword)) {
            throw new SecurityException("Current password is incorrect");
        }

        if (!validatePasswordStrength(newPassword)) {
            throw new IllegalArgumentException("New password does not meet strength requirements");
        }

        this.password = hashPassword(newPassword);
        logSecurityEvent("PASSWORD_CHANGED", "Password changed successfully");
        sendAccountNotification("Your password has been changed successfully.");
    }

    public String generateUserReport() {
        StringBuilder report = new StringBuilder();
        report.append("=== USER REPORT ===\n");
        report.append("Name: ").append(name).append("\n");
        report.append("Email: ").append(email).append("\n");
        report.append("Active: ").append(isActive).append("\n");
        report.append("Registration Date: ").append(registrationDate).append("\n");
        report.append("Login History: ").append(loginHistory.size()).append(" entries\n");
        return report.toString();
    }

    public void deleteAccount() {
        logSecurityEvent("ACCOUNT_DELETION_STARTED", "User initiated account deletion");
        this.isActive = false;
        this.email = "[DELETED]";
        this.password = null;
        this.loginHistory.clear();
        this.notifications.clear();
        dbService.deleteUser(name);
        logSecurityEvent("ACCOUNT_DELETED", "Account deletion completed");
    }

