public class Book {
    private String title;
    private String author;
    private String content;
    private String isbn;
    private java.util.Date publishDate;
    private String genre;
    private int pageCount;
    private double price;
    private String publisher;
    private java.util.List<String> reviews;
    private double averageRating;
    private int totalSales;
    private java.util.List<String> customerEmails;
    private boolean isAvailable;
    private String format;
    private double discountRate;

    private FileStorage fileStorage;
    private EmailService emailService;
    private DatabaseService dbService;
    private PrinterService printer;

    public Book(String title, String author, String content) {
        this.title = title;
        this.author = author;
        this.content = content;
        this.publishDate = new java.util.Date();
        this.reviews = new java.util.ArrayList<>();
        this.customerEmails = new java.util.ArrayList<>();
        this.averageRating = 0.0;
        this.totalSales = 0;
        this.isAvailable = true;
        this.format = "paperback";
        this.discountRate = 0.0;

        this.fileStorage = new FileStorage("/books/storage");
        this.emailService = new EmailService("smtp.bookstore.com");
        this.dbService = new DatabaseService("jdbc:mysql://localhost:3306/bookstore");
        this.printer = new PrinterService("BookStore_Printer_001");

        initializeBookDefaults();
    }

    public void printBook() {
        System.out.println("Title: " + title + "\nAuthor: " + author + "\nContent: " + content);
    }

    public void saveToFile(String filename) {
        String bookData = formatCompleteBookData();
        fileStorage.saveToFile(filename, bookData);
        dbService.saveBook(this);
    }

    public String formatCompleteBookData() {
        return "TITLE: " + title + "\nAUTHOR: " + author + "\nISBN: " + isbn + "\nGENRE: " + genre + "\nPAGES: " + pageCount + "\nPRICE: $" + calculateFinalPrice() + "\nFORMAT: " + format + "\nPUBLISHER: " + publisher + "\nRATING: " + averageRating + "\nSALES: " + totalSales + "\nAVAILABLE: " + isAvailable + "\nCONTENT: " + content;
    }

    public void generateUniqueISBN() {
        long timestamp = System.currentTimeMillis();
        String category = genre != null && genre.equals("fiction") ? "FIC" : "NF";
        this.isbn = "978-" + category + "-" + (timestamp % 100000) + "-" + String.format("%02d", (int)(Math.random() * 100));
    }

    public void calculateDynamicPageCount() {
        if (content != null) {
            int basePages = content.length() / 250;
            double formatMultiplier = format.equals("hardcover") ? 1.2 : 1.0;
            this.pageCount = Math.max(1, (int)(basePages * formatMultiplier));
        }
    }

    public boolean validateCompleteBookData() {
        return title != null && !title.trim().isEmpty() && 
               author != null && !author.trim().isEmpty() && 
               validateISBNFormat(isbn) && 
               validatePriceRange(price) && 
               content != null && content.length() > 0;
    }

    public boolean validateISBNFormat(String isbn) {
        if (isbn == null) return false;
        String clean = isbn.replaceAll("[^0-9X]", "");
        return clean.length() == 10 || clean.length() == 13;
    }

    public boolean validatePriceRange(double price) {
        return price >= 0.99 && price <= 999.99;
    }

    public void processCustomerReview(String customerEmail, String review, double rating) {
        if (rating >= 1.0 && rating <= 5.0) {
            reviews.add(review);
            customerEmails.add(customerEmail);
            recalculateRatingMetrics(rating);
            sendReviewConfirmationEmail(customerEmail);
            logReviewActivity(customerEmail, rating);
        }
    }

    public void recalculateRatingMetrics(double newRating) {
        averageRating = reviews.size() == 1 ? newRating : (averageRating * (reviews.size() - 1) + newRating) / reviews.size();
    }

    public void sendReviewConfirmationEmail(String customerEmail) {
        String subject = "Thank you for reviewing: " + title;
        String body = createReviewThankYouEmail();
        emailService.sendEmail(customerEmail, subject, body);
    }

    public String createReviewThankYouEmail() {
        return "Dear Reader,\n\nThank you for reviewing '" + title + "' by " + author + ".\nYour feedback helps other readers discover great books!\n\nBest regards,\nBookstore Team";
    }

    public void logReviewActivity(String customerEmail, double rating) {
        String logDetails = "Review added - Book: " + isbn + ", Customer: " + customerEmail + ", Rating: " + rating;
        dbService.logTransaction("REVIEW_ADDED", logDetails);
    }

    public void processSaleTransaction(String customerEmail) {
        totalSales++;
        customerEmails.add(customerEmail);

        updateInventoryStatus();

        dbService.updateSalesData(isbn, totalSales);

        String receiptEmail = generateSalesReceiptEmail();
        emailService.sendEmail(customerEmail, "Purchase Confirmation - " + title, receiptEmail);

        logSalesTransaction(customerEmail);

        if (totalSales % 100 == 0) {
            sendMilestoneNotification();
        }
    }

    public void updateInventoryStatus() {
        if (totalSales > 1000) {
            this.isAvailable = Math.random() > 0.1;
        }
    }

    public String generateSalesReceiptEmail() {
        double finalPrice = calculateFinalPrice();
        return "PURCHASE RECEIPT\n\nTitle: " + title + "\nAuthor: " + author + "\nISBN: " + isbn + "\nFormat: " + format + "\nOriginal Price: $" + price + "\nDiscount: " + (discountRate * 100) + "%\nFinal Price: $" + String.format("%.2f", finalPrice) + "\nThank you for your purchase!";
    }

    public void logSalesTransaction(String customerEmail) {
        String logDetails = "Sale completed - Book: " + isbn + ", Customer: " + customerEmail + ", Price: $" + calculateFinalPrice();
        dbService.logTransaction("SALE_COMPLETED", logDetails);
    }

    public void sendMilestoneNotification() {
        String subject = "Sales Milestone Reached: " + title;
        String body = "Congratulations! '" + title + "' has reached " + totalSales + " sales!";
        emailService.sendEmail("sales@bookstore.com", subject, body);
    }

    public double calculateFinalPrice() {
        return price * (1.0 - discountRate);
    }

    public double calculateAuthorRoyalty() {
        double baseRate = 0.10;
        if (totalSales > 5000) baseRate = 0.18;
        else if (totalSales > 1000) baseRate = 0.15;
        return totalSales * calculateFinalPrice() * baseRate;
    }

    public String generateComprehensiveReport() {
        double revenue = totalSales * calculateFinalPrice();
        double royalty = calculateAuthorRoyalty();
        return "=== COMPREHENSIVE BOOK REPORT ===\nTitle: " + title + "\nAuthor: " + author + "\nISBN: " + isbn + "\nGenre: " + genre + "\nFormat: " + format + "\nTotal Sales: " + totalSales + "\nRevenue: $" + String.format("%.2f", revenue) + "\nAuthor Royalty: $" + String.format("%.2f", royalty) + "\nAverage Rating: " + String.format("%.2f", averageRating) + "\nReviews: " + reviews.size() + "\nAvailable: " + isAvailable;
    }

    public void printDetailedReport() {
        String report = generateComprehensiveReport();
        System.out.println(report);
        printer.printReport(report);
    }

    public void sendMarketingCampaign() {
        if (customerEmails.size() > 0) {
            String campaignEmail = createMarketingEmail();
            emailService.sendBulkEmail(customerEmails, "New Release from " + author, campaignEmail);
            logMarketingActivity();
        }
    }

    public String createMarketingEmail() {
        return "Dear Valued Reader,\n\nSince you enjoyed '" + title + "', you might like our new releases from " + author + ".\nCheck out our latest collection with special discounts!\n\nHappy Reading!";
    }

    public void logMarketingActivity() {
        dbService.logTransaction("MARKETING_SENT", "Campaign sent for book: " + isbn + " to " + customerEmails.size() + " customers");
    }

    public void exportToMultipleFormats() {
        String jsonData = "{\"title\":\"" + title + "\",\"author\":\"" + author + "\",\"isbn\":\"" + isbn + "\",\"sales\":" + totalSales + ",\"rating\":" + averageRating + "}";
        fileStorage.saveToFile(isbn + ".json", jsonData);

        String xmlData = "<book><title>" + title + "</title><author>" + author + "</author><isbn>" + isbn + "</isbn><sales>" + totalSales + "</sales></book>";
        fileStorage.saveToFile(isbn + ".xml", xmlData);
    }

    public void initializeBookDefaults() {
        generateUniqueISBN();
        calculateDynamicPageCount();
        this.genre = "general";
        this.price = 19.99;
        this.publisher = "Independent Press";
    }

    public void applyDiscount(double discountPercentage) {
        if (discountPercentage >= 0.0 && discountPercentage <= 0.5) {
            this.discountRate = discountPercentage;
            notifyCustomersOfDiscount();
        }
    }

    public void notifyCustomersOfDiscount() {
        if (customerEmails.size() > 0) {
            String discountEmail = "Special Offer: " + (discountRate * 100) + "% off on '" + title + "'! Limited time only.";
            emailService.sendBulkEmail(customerEmails, "Special Discount - " + title, discountEmail);
        }
    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getAuthor() {
        return author;
    }

    public void setContent(String content) {
        this.content = content;
        calculateDynamicPageCount();
    }

    public void setPrice(double price) {
        if (validatePriceRange(price)) {
            this.price = price;
        }
    }

    public void setFormat(String format) {
        this.format = format;
        calculateDynamicPageCount();
    }
}

