public class Product {
    private String name;
    private double price;
    private String productId;
    private String category;
    private int stockQuantity;
    private double weight;
    private String description;
    private java.util.List<String> customerReviews;
    private double averageRating;
    private int totalSales;
    private double costPrice;
    private java.util.List<String> customerEmails;
    private boolean isActive;
    private String supplier;
    private double discountRate;
    private java.util.Map<String, Integer> salesByRegion;

    private InventoryDatabase database;
    private EmailService emailService;
    private PaymentProcessor paymentProcessor;
    private ShippingService shippingService;
    private AnalyticsService analytics;

    public Product(String name, double price) {
        this.name = name;
        this.price = price;
        this.productId = generateAdvancedProductId();
        this.customerReviews = new java.util.ArrayList<>();
        this.customerEmails = new java.util.ArrayList<>();
        this.salesByRegion = new java.util.HashMap<>();
        this.averageRating = 0.0;
        this.totalSales = 0;
        this.stockQuantity = 100;
        this.costPrice = price * 0.6;
        this.isActive = true;
        this.discountRate = 0.0;
        this.weight = 1.0;

        this.database = new InventoryDatabase("jdbc:mysql://localhost:3306/inventory");
        this.emailService = new EmailService("smtp.ecommerce.com");
        this.paymentProcessor = new PaymentProcessor("pay_api_key_123");
        this.shippingService = new ShippingService("FedEx");
        this.analytics = new AnalyticsService("analytics_key_456");

        initializeAdvancedDefaults();
    }

    public double applyDiscount(double percentage) {
        return price * (1 - percentage / 100);
    }

    public void displayProduct() {
        System.out.println("Product: " + name + ", Price: $" + price);
    }

    public String generateAdvancedProductId() {
        String categoryPrefix = category != null ? category.substring(0, Math.min(3, category.length())).toUpperCase() : "GEN";
        String timestamp = String.valueOf(System.currentTimeMillis() % 100000);
        String checksum = String.valueOf(Math.abs(name.hashCode() % 100));
        return categoryPrefix + "-" + timestamp + "-" + checksum;
    }

    public double calculateDynamicPricing() {
        double demandMultiplier = totalSales > 1000 ? 1.2 : (totalSales > 500 ? 1.1 : 1.0);
        double stockMultiplier = stockQuantity < 10 ? 1.15 : 1.0;
        double seasonalMultiplier = java.time.LocalDate.now().getMonthValue() == 12 ? 1.25 : 1.0;
        return price * demandMultiplier * stockMultiplier * seasonalMultiplier * (1 - discountRate);
    }

    public double calculateComplexProfitMargin() {
        double sellingPrice = calculateDynamicPricing();
        double shippingCost = shippingService.calculateShippingRate("domestic", weight);
        double totalCost = costPrice + shippingCost + (sellingPrice * 0.03);
        return ((sellingPrice - totalCost) / sellingPrice) * 100;
    }

    public double calculateTieredDiscount(int quantity) {
        if (quantity >= 100) return 0.20;
        if (quantity >= 50) return 0.15;
        if (quantity >= 10) return 0.10;
        if (quantity >= 5) return 0.05;
        return 0.0;
    }

    public boolean validateProductCompliance() {
        boolean hasValidName = name != null && name.length() >= 3 && name.length() <= 100;
        boolean hasValidPrice = price > 0 && price <= 10000;
        boolean hasValidWeight = weight > 0 && weight <= 50;
        boolean hasValidStock = stockQuantity >= 0;
        return hasValidName && hasValidPrice && hasValidWeight && hasValidStock;
    }

    public void processAdvancedReview(String customerEmail, String review, double rating, String region) {
        if (rating >= 1.0 && rating <= 5.0 && review.length() >= 10) {
            customerReviews.add(review);
            customerEmails.add(customerEmail);
            recalculateAdvancedRating(rating);

            String thankYouEmail = createReviewThankYouEmail(customerEmail, rating);
            emailService.sendEmail(customerEmail, "Thank you for your review!", thankYouEmail);

            java.util.Map<String, String> analyticsData = new java.util.HashMap<>();
            analyticsData.put("rating", String.valueOf(rating));
            analyticsData.put("region", region);
            analytics.trackEvent("REVIEW_ADDED", productId, analyticsData);

            database.logTransaction("REVIEW_PROCESSED", "Product: " + productId + ", Rating: " + rating + ", Region: " + region);
        }
    }

    public void recalculateAdvancedRating(double newRating) {
        if (customerReviews.size() == 1) {
            averageRating = newRating;
        } else {
            double weightedTotal = averageRating * (customerReviews.size() - 1) + newRating;
            averageRating = weightedTotal / customerReviews.size();
        }

        if (averageRating >= 4.5 && customerReviews.size() >= 10) {
            triggerBestSellerPromotion();
        }
    }

    public String createReviewThankYouEmail(String customerEmail, double rating) {
        StringBuilder email = new StringBuilder();
        email.append("Dear Valued Customer,\n\n");
        email.append("Thank you for your ").append(rating).append("-star review of ").append(name).append("!\n");
        email.append("Your feedback helps other customers make informed decisions.\n\n");
        if (rating >= 4.0) {
            email.append("As a token of appreciation, here's a 10% discount code: REVIEW10\n\n");
        }
        email.append("Best regards,\nCustomer Service Team");
        return email.toString();
    }

    public void triggerBestSellerPromotion() {
        String promoEmail = "BESTSELLER ALERT: " + name + " is now a top-rated product with " + averageRating + " stars!";
        emailService.sendBulkEmail(customerEmails, "Special Offer on Bestseller", promoEmail);
        analytics.trackEvent("BESTSELLER_PROMOTION", productId, new java.util.HashMap<>());
    }

    public String processComplexSale(int quantity, String customerEmail, String shippingAddress, String region, String cardNumber) {
        if (stockQuantity < quantity) {
            return "FAILED: Insufficient stock";
        }

        double unitPrice = calculateDynamicPricing();
        double discount = calculateTieredDiscount(quantity);
        double subtotal = unitPrice * quantity * (1 - discount);
        double shippingCost = shippingService.calculateShippingRate(region, weight * quantity);
        double totalAmount = subtotal + shippingCost;

        if (!paymentProcessor.processPayment(totalAmount, cardNumber)) {
            return "FAILED: Payment declined";
        }

        stockQuantity -= quantity;
        totalSales += quantity;
        salesByRegion.put(region, salesByRegion.getOrDefault(region, 0) + quantity);

        String trackingNumber = shippingService.createShipment(shippingAddress, weight * quantity);

        database.updateStock(productId, stockQuantity);

        String receiptEmail = generateAdvancedReceipt(quantity, unitPrice, discount, shippingCost, totalAmount, trackingNumber);
        emailService.sendEmail(customerEmail, "Order Confirmation - " + name, receiptEmail);

        checkAdvancedStockAlerts();

        java.util.Map<String, String> saleData = new java.util.HashMap<>();
        saleData.put("quantity", String.valueOf(quantity));
        saleData.put("amount", String.valueOf(totalAmount));
        saleData.put("region", region);
        analytics.trackEvent("SALE_COMPLETED", productId, saleData);

        database.logTransaction("COMPLEX_SALE", "Product: " + productId + ", Qty: " + quantity + ", Amount: $" + totalAmount + ", Region: " + region);

        return "SUCCESS: Order placed - Tracking: " + trackingNumber;
    }

    public String generateAdvancedReceipt(int quantity, double unitPrice, double discount, double shipping, double total, String tracking) {
        return "ORDER RECEIPT\n" +
               "Product: " + name + " (" + productId + ")\n" +
               "Quantity: " + quantity + "\n" +
               "Unit Price: $" + String.format("%.2f", unitPrice) + "\n" +
               "Discount: " + String.format("%.0f", discount * 100) + "%\n" +
               "Shipping: $" + String.format("%.2f", shipping) + "\n" +
               "Total: $" + String.format("%.2f", total) + "\n" +
               "Tracking: " + tracking + "\n" +
               "Thank you for your order!";
    }

    public void checkAdvancedStockAlerts() {
        if (stockQuantity <= 5) {
            String urgentAlert = "URGENT: Product " + name + " (" + productId + ") critically low - Only " + stockQuantity + " units left!";
            emailService.sendEmail("urgent@company.com", "Critical Stock Alert", urgentAlert);
            analytics.trackEvent("CRITICAL_STOCK_ALERT", productId, new java.util.HashMap<>());
        } else if (stockQuantity <= 20) {
            String alert = "LOW STOCK: Product " + name + " has " + stockQuantity + " units remaining.";
            emailService.sendEmail("inventory@company.com", "Low Stock Alert", alert);
        }
    }

    public void executeSmartRestock(String supplierEmail) {
        int recommendedStock = calculateOptimalStockLevel();
        int restockQuantity = recommendedStock - stockQuantity;

        if (restockQuantity > 0) {
            stockQuantity += restockQuantity;
            database.updateStock(productId, stockQuantity);

            String restockEmail = generateSmartRestockEmail(restockQuantity, recommendedStock);
            emailService.sendEmail(supplierEmail, "Smart Restock Completed - " + name, restockEmail);

            analytics.trackEvent("SMART_RESTOCK", productId, java.util.Map.of("quantity", String.valueOf(restockQuantity)));
            database.logTransaction("SMART_RESTOCK", "Product: " + productId + ", Added: " + restockQuantity + ", Target: " + recommendedStock);
        }
    }

    public int calculateOptimalStockLevel() {
        int averageMonthlySales = totalSales / Math.max(1, java.time.LocalDate.now().getMonthValue());
        int seasonalFactor = java.time.LocalDate.now().getMonthValue() == 12 ? 2 : 1;
        return averageMonthlySales * 2 * seasonalFactor;
    }

    public String generateSmartRestockEmail(int quantity, int targetLevel) {
        return "SMART RESTOCK REPORT\n" +
               "Product: " + name + " (" + productId + ")\n" +
               "Restocked Quantity: " + quantity + "\n" +
               "New Stock Level: " + stockQuantity + "\n" +
               "Target Level: " + targetLevel + "\n" +
               "Sales Velocity: " + (totalSales / Math.max(1, java.time.LocalDate.now().getDayOfYear())) + " units/day\n" +
               "Restock completed successfully.";
    }

    public String generateComprehensiveAnalytics() {
        double totalRevenue = totalSales * calculateDynamicPricing();
        double profitMargin = calculateComplexProfitMargin();
        String topRegion = salesByRegion.entrySet().stream().max(java.util.Map.Entry.comparingByValue()).map(java.util.Map.Entry::getKey).orElse("N/A");

        return "COMPREHENSIVE ANALYTICS\n" +
               "Product: " + name + " (" + productId + ")\n" +
               "Total Sales: " + totalSales + " units\n" +
               "Revenue: $" + String.format("%.2f", totalRevenue) + "\n" +
               "Profit Margin: " + String.format("%.2f", profitMargin) + "%\n" +
               "Average Rating: " + String.format("%.2f", averageRating) + " (" + customerReviews.size() + " reviews)\n" +
               "Top Region: " + topRegion + "\n" +
               "Stock Level: " + stockQuantity + "\n" +
               "Current Price: $" + String.format("%.2f", calculateDynamicPricing());
    }

    public void launchMarketingCampaign(String campaignType) {
        String campaignEmail = createCampaignEmail(campaignType);
        emailService.sendBulkEmail(customerEmails, "Special Campaign - " + name, campaignEmail);

        java.util.Map<String, String> campaignData = new java.util.HashMap<>();
        campaignData.put("type", campaignType);
        campaignData.put("reach", String.valueOf(customerEmails.size()));
        analytics.trackEvent("MARKETING_CAMPAIGN", productId, campaignData);

        database.logTransaction("CAMPAIGN_LAUNCHED", "Product: " + productId + ", Type: " + campaignType + ", Reach: " + customerEmails.size());
    }

    public String createCampaignEmail(String campaignType) {
        if (campaignType.equals("SEASONAL")) {
            return "Don't miss our seasonal special on " + name + "! Limited time offer with up to 25% off!";
        } else if (campaignType.equals("CLEARANCE")) {
            return "CLEARANCE ALERT: " + name + " must go! Huge discounts available now!";
        } else {
            return "Special promotion on " + name + " - Check out our latest deals!";
        }
    }

    public void initializeAdvancedDefaults() {
        this.category = "Electronics";
        this.description = "High-quality product";
        this.supplier = "Global Supplier Inc";
        salesByRegion.put("North America", 0);
        salesByRegion.put("Europe", 0);
        salesByRegion.put("Asia", 0);
    }

