class User:
    def __init__(self, name: str, email: str):
        self.name = name
        self.email = email
        self.password: Optional[str] = None
        self.is_active = True
        self.role = "USER"
        self.last_login: Optional[datetime] = None
        self.login_attempts = 0
        self.database = DatabaseHelper("mysql://localhost:3306/users")
        self.email_helper = EmailHelper("smtp.company.com")

    def save_to_database(self):
        user_data = f"User: {self.name}, Email: {self.email}, Role: {self.role}"
        self.database.save_user(user_data)
        print(f"Saving user {self.name} to database")

    def send_welcome_email(self):
        self.email_helper.send_email(self.email, "Welcome", f"Welcome {self.name}!")
        print(f"Sending welcome email to {self.email}")

    def validate_email(self, email: str) -> bool:
        if not email or len(email) == 0:
            return False
        return "@" in email and "." in email

    def validate_password(self, password: str) -> bool:
        if not password or len(password) < 8:
            return False

        has_upper = any(c.isupper() for c in password)
        has_lower = any(c.islower() for c in password)
        has_digit = any(c.isdigit() for c in password)

        return has_upper and has_lower and has_digit

    def hash_password(self, password: str) -> str:
        hash_value = 0
        for c in password:
            hash_value = hash_value * 31 + ord(c)
        return str(abs(hash_value))

    def authenticate(self, password: str) -> bool:
        if self.login_attempts >= 5:
            print("Account locked due to too many failed attempts")
            return False

        if self.password and self.password == self.hash_password(password):
            self.login_attempts = 0
            self.last_login = datetime.now()
            self.database.update_user(self.email, f"Last login: {self.last_login}")
            return True

        self.login_attempts += 1
        return False

    def lock_account(self):
        self.is_active = False
        self.database.update_user(self.email, "Account locked")
        self.email_helper.send_email(self.email, "Account Locked", "Your account has been locked")
        print(f"Account locked for user: {self.name}")

    def unlock_account(self):
        self.is_active = True
        self.login_attempts = 0
        self.database.update_user(self.email, "Account unlocked")
        print(f"Account unlocked for user: {self.name}")

    def get_name(self) -> str:
        return self.name

    def set_name(self, name: str):
        self.name = name

    def get_email(self) -> str:
        return self.email

    def set_email(self, email: str):
        self.email = email

    def get_password(self) -> Optional[str]:
        return self.password

    def set_password(self, password: str):
        self.password = self.hash_password(password)

    def is_user_active(self) -> bool:
        return self.is_active

    def get_role(self) -> str:
        return self.role

    def set_role(self, role: str):
        self.role = role

    def get_last_login(self) -> Optional[datetime]:
        return self.last_login

    def get_login_attempts(self) -> int:
        return self.login_attempts

