class Employee:
    def __init__(self, name: str, base_salary: float, years_of_service: int):
        self.name = name
        self.base_salary = base_salary
        self.years_of_service = years_of_service
        self.department: Optional[str] = None
        self.position: Optional[str] = None
        self.employee_id = self.generate_employee_id()
        self.hire_date = datetime.now()
        self.last_review_date: Optional[datetime] = None
        self.performance_rating = 3.0
        self.vacation_days = 20
        self.used_vacation_days = 0
        self.manager: Optional[str] = None
        self.email: Optional[str] = None

        self.hr_system = HRSystem("https://hr.company.com")
        self.notification_service = NotificationService("smtp.company.com")

    def calculate_salary(self) -> float:
        return self.base_salary + (self.years_of_service * 1000)

    def print_pay_slip(self):
        print(f"Pay slip for {self.name}: ${self.calculate_salary()}")

    def calculate_bonus(self) -> float:
        base_bonus = self.base_salary * 0.1
        if self.performance_rating >= 4.0:
            base_bonus *= 1.5
        elif self.performance_rating >= 3.5:
            base_bonus *= 1.2
        return base_bonus

    def calculate_annual_salary(self) -> float:
        return self.calculate_salary() * 12 + self.calculate_bonus()

    def process_payroll(self):
        monthly_salary = self.calculate_salary()
        taxes = self.calculate_taxes(monthly_salary)
        net_pay = monthly_salary - taxes

        print(f"Processing payroll for {self.name}")
        print(f"Gross Pay: ${monthly_salary}")
        print(f"Taxes: ${taxes}")
        print(f"Net Pay: ${net_pay}")

        self.hr_system.update_employee_record(self.employee_id, f"Payroll processed: ${net_pay}")
        self.send_payroll_email()

    def calculate_taxes(self, salary: float) -> float:
        if salary <= 3000:
            return salary * 0.15
        elif salary <= 6000:
            return salary * 0.20
        else:
            return salary * 0.25

    def request_vacation(self, days: int) -> bool:
        if self.used_vacation_days + days <= self.vacation_days:
            self.used_vacation_days += days
            print(f"Vacation request approved for {self.name}: {days} days")
            self.hr_system.update_employee_record(self.employee_id, f"Vacation approved: {days} days")
            self.notify_manager(f"Vacation request approved for {self.name}")
            return True
        else:
            print(f"Vacation request denied for {self.name}: insufficient days")
            return False

    def notify_manager(self, message: str):
        if self.manager:
            self.notification_service.notify_manager(self.manager, message)

    def send_payroll_email(self):
        if self.email:
            self.notification_service.send_email(self.email, "Your monthly payslip", "Please find your payslip attached.")

    def conduct_performance_review(self):
        print(f"Conducting performance review for {self.name}")
        print(f"Current rating: {self.performance_rating}")
        self.last_review_date = datetime.now()

        self.hr_system.log_performance_review(self.employee_id, self.performance_rating)

        if self.performance_rating >= 4.0:
            print("Excellent performance! Recommending for promotion.")
        elif self.performance_rating < 2.0:
            print("Performance improvement needed.")

    def update_performance_rating(self, rating: float):
        if 1.0 <= rating <= 5.0:
            self.performance_rating = rating
            print(f"Performance rating updated to {rating} for {self.name}")
            self.hr_system.update_employee_record(self.employee_id, f"Performance rating: {rating}")
        else:
            print("Invalid rating. Must be between 1.0 and 5.0")

    def generate_employee_id(self) -> str:
        return f"EMP{int(datetime.now().timestamp()) % 10000}"

    def print_employee_report(self):
        print(f"Employee Report for {self.name}")
        print(f"ID: {self.employee_id}")
        print(f"Department: {self.department}")
        print(f"Position: {self.position}")
        print(f"Hire Date: {self.hire_date}")
        print(f"Years of Service: {self.years_of_service}")
        print(f"Base Salary: ${self.base_salary}")
        print(f"Performance Rating: {self.performance_rating}")
        print(f"Vacation Days Remaining: {self.vacation_days - self.used_vacation_days}")

    # Getters and Setters
    def get_name(self) -> str:
        return self.name

    def set_name(self, name: str):
        self.name = name

    def get_base_salary(self) -> float:
        return self.base_salary

    def set_base_salary(self, base_salary: float):
        self.base_salary = base_salary

    def get_years_of_service(self) -> int:
        return self.years_of_service

    def set_years_of_service(self, years_of_service: int):
        self.years_of_service = years_of_service

    def get_department(self) -> Optional[str]:
        return self.department

    def set_department(self, department: str):
        self.department = department

    def get_position(self) -> Optional[str]:
        return self.position

    def set_position(self, position: str):
